#include <stdio.h>
#include <stdlib.h>

int getMoneyAmount(int n) {
    int size = n + 2;
    int *dp = (int *)calloc((size_t)size * size, sizeof(int));
    if (dp == NULL) return 0;

    #define DP(l, r) dp[(l) * size + (r)]
    for (int len = 2; len <= n; ++len) {
        for (int left = 1; left + len - 1 <= n; ++left) {
            int right = left + len - 1;
            int best = 2147483647;
            for (int guess = left; guess < right; ++guess) {
                int leftCost = DP(left, guess - 1);
                int rightCost = DP(guess + 1, right);
                int cost = guess + (leftCost > rightCost ? leftCost : rightCost);
                if (cost < best) best = cost;
            }
            DP(left, right) = best;
        }
    }

    int result = DP(1, n);
    free(dp);
    return result;
}

